function appendPostMedia(container,items=[]){if(!items.length)return;const gallery=el('div','post-media');for(const m of items){const item=el(m.mime==='video/mp4'?'video':'img');item.src=m.url;if(m.mime==='video/mp4'){item.controls=true;item.preload='metadata';item.playsInline=true;item.setAttribute('aria-label',m.alt||'Attached video');}else{item.alt=m.alt;item.loading='lazy';}gallery.append(item);}container.append(gallery);}
