function clearMedia(){for(const m of pendingMedia)URL.revokeObjectURL(m.preview);pendingMedia=[];renderMediaPreview();}
function photosAllowed(){return !!state.me?.plus||(state.me?.americanStatus==='verified'&&Date.now()-Date.parse(state.me.americanVerification?.checkedAt)<90*86400000);}
function updateComposerPlan(){const plus=!!state.me?.plus;const photos=photosAllowed();$('#post-images').disabled=!photos||uploadingMedia;$('#post-video').disabled=!plus||uploadingMedia;$('#media-upgrade').classList.toggle('hidden',plus);$('#media-upgrade').textContent=photos?'Unlock videos with Plus ↗':'Unlock photos and videos with Plus ↗';$('#media-verify').classList.toggle('hidden',photos);$('#char-count').textContent=[...segmenter.segment($('#post-text').value)].length+' / '+(plus?833:300);if(pendingMedia.some(m=>m.mime==='video/mp4'?!plus:!photos))clearMedia();}
function renderMediaPreview(){const panel=$('#media-preview');panel.replaceChildren();for(const m of pendingMedia){const card=el('div','attachment-preview');const preview=el(m.mime==='video/mp4'?'video':'img');preview.src=m.preview;if(m.mime==='video/mp4'){preview.controls=true;preview.preload='metadata';}else preview.alt='Your image attachment';const label=el('label','','Description (optional)');const alt=el('textarea');alt.maxLength=2000;alt.value=m.alt;alt.oninput=()=>m.alt=alt.value;label.append(alt);const remove=el('button','text-button','Remove');remove.type='button';remove.disabled=uploadingMedia;remove.onclick=()=>{pendingMedia=pendingMedia.filter(x=>x!==m);URL.revokeObjectURL(m.preview);renderMediaPreview();};card.append(preview,label,remove);panel.append(card);}}
async function resizePostImage(file){if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>20000000)throw Error('Choose PNG, JPEG, or WebP images under 20 MB.');const bitmap=await createImageBitmap(file);try{const canvas=document.createElement('canvas');const scale=Math.min(1,1600/Math.max(bitmap.width,bitmap.height));canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);for(const quality of [.85,.7,.5,.35]){const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/webp',quality));if(blob&&blob.size<=1000000)return blob;}throw Error('This image is too large after resizing. Choose a smaller image.');}finally{bitmap.close();}}
async function uploadSelected(files,video=false){if(!requireMe())return;if(video?!state.me.plus:!photosAllowed()){navigate(video?'plus':'account');return;}if(uploadingMedia){toast('Wait for the current uploads to finish.');return;}if(!files.length)return;if(video?(pendingMedia.length||files.length!==1):(pendingMedia.some(m=>m.mime==='video/mp4')||pendingMedia.length+files.length>4)){toast('Attach up to four images or one video.');return;}uploadingMedia=true;$('#composer button[type=submit]').disabled=true;$('#post-images').disabled=true;$('#post-video').disabled=true;renderMediaPreview();try{for(const file of files){$('#media-status').textContent='Uploading '+file.name+'…';const videoMime=file.type==='video/quicktime'||/\.mov$/i.test(file.name)?'video/quicktime':'video/mp4';if(video&&(!['video/mp4','video/quicktime'].includes(file.type)&&! /\.(mp4|mov)$/i.test(file.name)||file.size>250000000))throw Error('Choose an MP4 or iPhone MOV video under 250 MB (0.25 GB) and no longer than 60 seconds.');const blob=video?file:await resizePostImage(file);const response=await fetch('/api/media/upload',{method:'POST',headers:{Authorization:'Bearer '+state.token,'Content-Type':video?videoMime:blob.type},body:blob});const result=await response.json();if(!response.ok)throw Error(result.error||'Media upload failed.');pendingMedia.push({...result,alt:'',preview:URL.createObjectURL(blob)});renderMediaPreview();}$('#media-status').textContent='Attachments ready.';}catch(e){$('#media-status').textContent=e.message;}finally{uploadingMedia=false;$('#composer button[type=submit]').disabled=false;updateComposerPlan();$('#post-images').value='';$('#post-video').value='';renderMediaPreview();}}
