async function setupCaptcha(){clearCaptcha();const config=state.config?.captcha;const active=config?.enabled;$('#captcha-panel').classList.toggle('hidden',!active);if(!active)return;const generation=captchaGeneration;$('#captcha-status').textContent='Loading human verification…';try{if(!config.siteKey)throw Error('Human verification is unavailable. Please try again later.');if(!window.turnstile){if(!turnstileLoader)turnstileLoader=new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='https://challenges.cloudflare.com/turnstile/v0/api.js?render=explicit';script.async=true;script.onload=resolve;script.onerror=()=>reject(Error('Could not load human verification. Check your connection and try again.'));document.head.append(script);});await turnstileLoader;}if(generation!==captchaGeneration||!$('#auth-dialog').open)return;captchaWidget=window.turnstile.render('#captcha-widget',{sitekey:config.siteKey,action:state.register?'human-register':'human-login',theme:'dark',size:$('#captcha-widget').clientWidth<300?'compact':'flexible',callback:token=>{captchaToken=token;$('#captcha-status').textContent='Human verification complete.';},'expired-callback':()=>{captchaToken='';$('#captcha-status').textContent='Verification expired. Please verify again.';},'error-callback':()=>{captchaToken='';$('#captcha-status').textContent='Verification could not complete. Retry below.';}});}catch(e){turnstileLoader=null;$('#captcha-status').textContent=e.message;}}
